"""Declarative base and shared column mixins.

Every model inherits from `Base`. Alembic autogenerate reads `Base.metadata`, so
each model module must be imported before a migration is generated - see
`app/db/models/__init__.py`, which is the single place that registers them.
"""

from datetime import datetime

from sqlalchemy import DateTime, MetaData, func
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

# Explicit naming convention so Alembic emits stable, predictable constraint
# names instead of database-generated ones. Without this, autogenerated
# migrations can produce unnamed constraints that later revisions cannot drop.
NAMING_CONVENTION = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING_CONVENTION)


class TimestampMixin:
    """created_at / updated_at maintained by the database itself.

    `server_default`/`onupdate` mean the timestamps are correct even for writes
    that bypass the ORM (bulk inserts, raw SQL, psql), which a Python-side
    default would miss.
    """

    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
        onupdate=func.now(),
    )
